if (!root) {
    root = new TreeNode(item);
    return;
}
TreeNode* current = root;
while (true) {
    if (item < current->val) {
        if (!current->left) {
            current->left = new TreeNode(item);
            return;
        }
        current = current->left;
    } else {
        if (!current->right) {
            current->right = new TreeNode(item);
            return;
        }
        current = current->right;
    }
}
// END_CODE

